using System;
using System.IO;
using System.Linq;
using InsaneDreams.Combat;
using InsaneDreams.Enemies;
using InsaneDreams.Inventory;
using InsaneDreams.Missions;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;
public static class Level1CombatHotfixSetup
{
    const string Folder="Assets/Data/FirstOperation";
    static void Edit(Object o,Action<SerializedObject> change){var s=new SerializedObject(o);change(s);s.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(o);}
    public static string Geometry()=>Newtonsoft.Json.JsonConvert.SerializeObject(UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().Where(g=>g.name=="FirstOperationTerrain"||g.name=="FirstOperationScenery").SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Select(t=>new{t.name,p=new[]{t.position.x,t.position.y,t.position.z},s=new[]{t.lossyScale.x,t.lossyScale.y,t.lossyScale.z},box=t.GetComponent<BoxCollider2D>()!=null?new{size=new[]{t.GetComponent<BoxCollider2D>().size.x,t.GetComponent<BoxCollider2D>().size.y},offset=new[]{t.GetComponent<BoxCollider2D>().offset.x,t.GetComponent<BoxCollider2D>().offset.y},trigger=t.GetComponent<BoxCollider2D>().isTrigger}:null}));
    static object Values(Object o)=>Newtonsoft.Json.Linq.JObject.Parse(EditorJsonUtility.ToJson(o));
    static void Samurai(GameObject actor)
    {Edit(actor.GetComponent<SamuraiCombat>(),s=>{s.FindProperty("recoverySeconds").floatValue=.42f;s.FindProperty("jumpSampleSeconds").floatValue=.2f;s.FindProperty("jumpCooldown").floatValue=.85f;});Edit(actor.GetComponent<EnemyCombat>(),s=>{s.FindProperty("reactionSeconds").floatValue=.02f;s.FindProperty("reactionJitterSeconds").floatValue=.02f;});Edit(actor.GetComponent<InsaneDreams.Prototype.PlayerMotor2D>(),s=>s.FindProperty("moveSpeed").floatValue=9.5f);}
    static Health AddGuard(MissionEncounter group,string name,float x,float floor,string personality)
    {
        var existing=group.transform.Find(name);if(existing!=null)return ((LarperBrain)new SerializedObject(existing.GetComponent<EnemySpawnPoint>()).FindProperty("placedActor").objectReferenceValue).GetComponent<Health>();
        var kind=AssetDatabase.LoadAssetAtPath<EnemyArchetype>("Assets/Data/Enemies/Larper.asset");var actor=(GameObject)PrefabUtility.InstantiatePrefab(kind.Prefab,group.gameObject.scene);actor.name=name+"_Actor";actor.transform.SetParent(group.transform);var b=actor.GetComponent<BoxCollider2D>();Vector2 at=new Vector2(x,floor+b.size.y/2-b.offset.y+.03f);actor.transform.position=at;actor.GetComponent<Rigidbody2D>().position=at;Edit(actor.GetComponent<EnemyCombat>(),s=>{s.FindProperty("reactionSeconds").floatValue=.7f;s.FindProperty("reactionJitterSeconds").floatValue=.12f;});var go=new GameObject(name);go.transform.SetParent(group.transform);go.transform.position=at;var point=go.AddComponent<EnemySpawnPoint>();Edit(point,s=>{s.FindProperty("archetype").objectReferenceValue=kind;s.FindProperty("spawnOnStart").boolValue=false;s.FindProperty("placedActor").objectReferenceValue=actor.GetComponent<LarperBrain>();s.FindProperty("spawnedParent").objectReferenceValue=group.transform;s.FindProperty("personality").objectReferenceValue=AssetDatabase.LoadAssetAtPath<LarperPersonalityProfile>("Assets/Data/Enemies/Personalities/"+personality+".asset");});Edit(group,s=>{var a=s.FindProperty("points");int n=a.arraySize;a.arraySize=n+1;a.GetArrayElementAtIndex(n).objectReferenceValue=point;});return actor.GetComponent<Health>();
    }
    public static string Apply(bool applyPopulation=true)
    {
        if(EditorApplication.isPlaying)throw new InvalidOperationException("Stop Play Mode");if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new InvalidOperationException("Save the current scene before authoring");var scene=EditorSceneManager.OpenScene("Assets/Scenes/Warehouse_Demo.unity");var m=Object.FindAnyObjectByType<WarehouseMission>();var before=Geometry();
        var officerPrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/Officer.prefab");var samuraiBase=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Enemies/Samurai.prefab");var rocket=AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/OperationFirework.prefab");var gun=AssetDatabase.LoadAssetAtPath<WeaponDefinition>(Folder+"/OfficerPistol.asset");
        string evidence="TestResults/Level1CombatHotfix/";if(!File.Exists(evidence+"Before.json"))File.WriteAllText(evidence+"Before.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{samurai=Values(samuraiBase.GetComponent<SamuraiCombat>()),motor=Values(samuraiBase.GetComponent<InsaneDreams.Prototype.PlayerMotor2D>()),officer=Values(officerPrefab.GetComponent<EnemyCombat>()),telegraph=Values(officerPrefab.GetComponent<OfficerShotTelegraph>()),gun=Values(gun),rocket=Values(rocket.GetComponent<FireworkProjectile>())},Newtonsoft.Json.Formatting.Indented));File.WriteAllText(evidence+"GeometryBefore.json",before);
        Edit(gun,s=>{s.FindProperty("displayName").stringValue="Desert Eagle";s.FindProperty("description").stringValue="Officer's heavy semi-automatic pistol: one deliberate shot after a red laser warning.";s.FindProperty("damage").floatValue=42;s.FindProperty("firingInterval").floatValue=2.4f;s.FindProperty("magazineCapacity").intValue=7;s.FindProperty("magazineSprite").objectReferenceValue=null;s.FindProperty("impactImpulse").floatValue=1.5f;});
        var op=PrefabUtility.LoadPrefabContents(Folder+"/Officer.prefab");try{Edit(op.GetComponent<OfficerShotTelegraph>(),s=>{s.FindProperty("windupSeconds").floatValue=1;s.FindProperty("commitSeconds").floatValue=.2f;s.FindProperty("shotCooldown").floatValue=2.4f;s.FindProperty("retreatDistance").floatValue=6;});Edit(op.GetComponent<EnemyCombat>(),s=>{s.FindProperty("preferredDistance").floatValue=10;s.FindProperty("coverSearchDistance").floatValue=9;s.FindProperty("withdrawalDistance").floatValue=7;s.FindProperty("combatRepositionChance").floatValue=.9f;});Edit(op.GetComponent<CombatFeedback>(),s=>{s.FindProperty("volume").floatValue=.65f;var list=s.FindProperty("shotAnchoredFlashWeapons");list.arraySize=1;list.GetArrayElementAtIndex(0).objectReferenceValue=gun;});PrefabUtility.SaveAsPrefabAsset(op,Folder+"/Officer.prefab");}finally{PrefabUtility.UnloadPrefabContents(op);}
        op=PrefabUtility.LoadPrefabContents(Folder+"/OperationFirework.prefab");try{Edit(op.GetComponent<FireworkProjectile>(),s=>{s.FindProperty("damage").floatValue=100;s.FindProperty("useRadialFalloff").boolValue=true;s.FindProperty("minimumEffectiveDamage").floatValue=0;s.FindProperty("damageFalloff").animationCurveValue=new AnimationCurve(new Keyframe(0,1),new Keyframe(.25f,.85f),new Keyframe(.5f,.5f),new Keyframe(.75f,.2f),new Keyframe(1,0));});PrefabUtility.SaveAsPrefabAsset(op,Folder+"/OperationFirework.prefab");}finally{PrefabUtility.UnloadPrefabContents(op);}
        string samuraiPath=Folder+"/OperationSamurai.prefab";op=PrefabUtility.LoadPrefabContents("Assets/Prefabs/Enemies/Samurai.prefab");try{Samurai(op);PrefabUtility.SaveAsPrefabAsset(op,samuraiPath);}finally{PrefabUtility.UnloadPrefabContents(op);}
        var kind=AssetDatabase.LoadAssetAtPath<EnemyArchetype>(Folder+"/OperationSamurai.asset");if(kind==null){kind=Object.Instantiate(AssetDatabase.LoadAssetAtPath<EnemyArchetype>("Assets/Data/Enemies/Samurai.asset"));kind.name="OperationSamurai";AssetDatabase.CreateAsset(kind,Folder+"/OperationSamurai.asset");Edit(kind,s=>s.FindProperty("stableId").stringValue=Guid.NewGuid().ToString("N"));}Edit(kind,s=>s.FindProperty("prefab").objectReferenceValue=AssetDatabase.LoadAssetAtPath<GameObject>(samuraiPath));
        var point=m.Encounters[2].Points[0];var samurai=(LarperBrain)new SerializedObject(point).FindProperty("placedActor").objectReferenceValue;Samurai(samurai.gameObject);Edit(point,s=>s.FindProperty("archetype").objectReferenceValue=kind);Edit(samurai,s=>s.FindProperty("archetype").objectReferenceValue=kind);
        if(applyPopulation)AddGuard(m.Encounters[1],"CombatHotfix_StorageGuard",10,0,"Cowardly");var ally=applyPopulation?AddGuard(m.Encounters[4],"CombatHotfix_CommandGuard",129,3.2f,"Ordinary"):null;var officerPoint=m.Encounters[4].Points[0];var officer=(LarperBrain)new SerializedObject(officerPoint).FindProperty("placedActor").objectReferenceValue;
        Edit(officerPoint,s=>s.FindProperty("personality").objectReferenceValue=AssetDatabase.LoadAssetAtPath<LarperPersonalityProfile>("Assets/Data/Enemies/Personalities/Cowardly.asset"));Edit(officer.GetComponent<OfficerShotTelegraph>(),s=>{var a=s.FindProperty("nearbyAllies");a.arraySize=ally!=null?1:0;if(ally!=null)a.GetArrayElementAtIndex(0).objectReferenceValue=ally;});
        var level=Object.FindAnyObjectByType<InsaneDreams.Level.LevelEntry>();var points=m.Encounters.SelectMany(g=>g.Points).ToArray();Edit(level,s=>{var a=s.FindProperty("encounters");a.arraySize=points.Length;for(int i=0;i<points.Length;i++)a.GetArrayElementAtIndex(i).objectReferenceValue=points[i];});
        string after=Geometry();File.WriteAllText(evidence+"GeometryAfter.json",after);if(before!=after)throw new Exception("Hotfix must not change geometry");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();return points.Length+" occupants; geometry unchanged; scoped Samurai, Desert Eagle/laser Officer, radial explosives.";
    }
}